    // -25, -20, ..., -5 (continuing clockwise back up to the top -- the left/before-start half, read
    // in the direction the hand actually sweeps as the countdown runs down toward 0).
    for(let i=0;i<12;i++){
      const a = i/12 * 2*Math.PI;
