  // person clicking through a cycle repeatedly sometimes lands two genuine, separate press/release
  // gestures close enough together to read as an accidental double-click, advancing the cycle twice
  // for what felt like one click. This can't be caught at the browser's own dblclick event (the app
  // doesn't special-case double-clicks on an individual smart-shape handle, only on the shape's own
  // body), so it's handled entirely in-script instead: each handle stores its OWN last-resolved
  // timestamp in `state` (`_click_event`/`_click_p2cycle`/`_click_orange` -- three separate fields, so
  // clicking one icon never debounces a different one) and a click arriving inside this window is a
  // silent no-op (same `state` returned, timestamp left untouched, so it doesn't itself start a new
  // window). `Date.now()` is ordinary JS, available here since scripts run in the page's own real
  // global scope (see CLAUDE.md's "Accepted risk" note), not a sandbox.
  _CLICK_DEBOUNCE_MS: 350,
  _debounced(state, key, now){
    const last = state['_click_'+key];
    return !!(last && now - last < this._CLICK_DEBOUNCE_MS);
  },

  dragEdit(state, handle, lx, ly, w, h, style){
    if(handle === 'hand'){
      const L = this._layout(style||{}, w, h);
      let a = Math.atan2(lx-L.clockCx, -(ly-L.clockCy)); if(a<0) a += 2*Math.PI;
      // Inverse of _dialAngle: a<=π is the RIGHT half (after start, value 0..30), a>π is the LEFT half
      // (before start, value -30..0, wrapping down from just-under-0 as a approaches 2π).
      let value = Math.round(a <= Math.PI ? (a/Math.PI)*30 : (a/Math.PI)*30 - 60);
      value = Math.max(-30, Math.min(30, value));
      // Dragging the hand to anywhere BEFORE the start cancels a stale X/recall/N override outright
      // (not just hides it) -- so dragging the hand back to AFTER the start later doesn't resurrect
      // it. AP is left untouched there -- it's explicitly still allowed before the start. The mirror
      // case: dragging the hand past the start (value > 0) cancels a stale AP the same way -- AP can
      // never apply after the start.
      const staleBeforeStart = this._beforeStart({value}) && (state.event==='X' || state.event==='recall' || state.event==='N');
      const staleAP = this._afterStart({value}) && state.event==='AP';
      if(staleBeforeStart || staleAP){
        return { ...state, value, event: null, sub: null };
      }
      return { ...state, value };
    }
    const now = Date.now();
    if(handle === 'event'){
      if(this._debounced(state, 'event', now)) return state;
      // Before the start, only AP is offered -- cycling through X/recall/N here would immediately get
      // cancelled again by the hand-drag reset above anyway, so they're left out of the cycle itself
      // rather than being reachable-then-instantly-undone. Past the start (right half of the dial),
      // it's the mirror case: AP itself is left out instead, for the exact same reason (it'd just get
      // cancelled again by the hand-drag reset's own AP check). Only exactly AT the start (value:0,
      // neither half) does the full 5-state cycle apply.
      const cycle = this._beforeStart(state) ? [null,'AP']
        : this._afterStart(state) ? this._EVENT_CYCLE.filter(e => e!=='AP')
        : this._EVENT_CYCLE;
      const i = cycle.indexOf(this._effectiveEvent(state));
      const next = cycle[(i<0?0:i+1) % cycle.length];
      return { ...state, event: next, sub: (next==='AP'||next==='N') ? state.sub : null, _click_event: now };
    }
    if(handle === 'p2cycle'){
      if(this._debounced(state, 'p2cycle', now)) return state;
      if(state.event === 'AP' || state.event === 'N'){
        const i = this._SUB_CYCLE.indexOf(state.sub);
        return { ...state, sub: this._SUB_CYCLE[(i+1) % this._SUB_CYCLE.length], _click_p2cycle: now };
      }
      if(state.event === null){
        const i = this._PREP_CYCLE.indexOf(state.prep);
        return { ...state, prep: this._PREP_CYCLE[(i+1) % this._PREP_CYCLE.length], _click_p2cycle: now };
      }
      return state;  // X / general recall have no secondary flag to cycle
    }
    if(handle === 'orange'){
      if(this._debounced(state, 'orange', now)) return state;
      return { ...state, orangeShown: !state.orangeShown, _click_orange: now };
    }
    return state;
  },
})

// Wall-clock readings and nominal 100 ms boundary pulses in a selected timezone.
// Reopening, changing timezone, and missed/adjusted clock time re-prime without replaying ticks.
// The host schedules transitions; compute and image exports use the last settled snapshot.
({
  apiVersion:2,
  wakePolicy:'latest',
  inputs:{timezone:{role:'control',type:'string',default:'local'}},
  outputs:{second:{role:'control',type:'boolean'},minute:{role:'control',type:'boolean'},hour:{role:'control',type:'boolean'},halfDay:{role:'control',type:'boolean'},time:{type:'string'}},
  initState(){return {time:'00:00:00',second:false,minute:false,hour:false,halfDay:false,showIndicators:true};},
  initStyle(){return {w:220,h:300,strokeOn:false,fontSize:16};},
  _formatter(timezone){
    if(typeof timezone!=='string' || !timezone.trim() || timezone.length>128)throw new Error('Timezone must be local or a valid timezone name, such as Europe/Berlin');
    const zone=timezone.trim();
    try{return new Intl.DateTimeFormat('en-GB',{...(zone.toLowerCase()==='local'?{}:{timeZone:zone}),
      hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23',numberingSystem:'latn'});}
    catch(_){throw new Error('Invalid timezone: use local, UTC, or a timezone name such as Europe/Berlin');}
  },
  _validate(state){
    if(typeof state.time!=='string' || !/^(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d$/.test(state.time) ||
       ['second','minute','hour','halfDay'].some(key=>typeof state[key]!=='boolean') || typeof state.showIndicators!=='boolean')throw new Error('Invalid Live clock state');
  },
  transition(inputs,state,memory,context){
    const {now}=context;
    this._validate(state);
    if(!Number.isFinite(now) || now<0)throw new Error('Live clock requires a valid monotonic time');
    const formatter=this._formatter(inputs.timezone),wall=Date.now();
    if(!Number.isFinite(wall) || Math.abs(wall)>8640000000000000)throw new Error('Live clock requires a valid wall-clock time');
    const parts=Object.fromEntries(formatter.formatToParts(new Date(wall)).map(part=>[part.type,part.value]));
    const hour=Number(parts.hour)%24,minute=Number(parts.minute),second=Number(parts.second);
    const time=[hour,minute,second].map(value=>String(value).padStart(2,'0')).join(':');
    const zone=formatter.resolvedOptions().timeZone,epochSecond=Math.floor(wall/1000);
    const fresh=memory==null || (typeof memory==='object' && !Array.isArray(memory) && Object.keys(memory).length===0);
    if(!fresh && (typeof memory.zone!=='string' || !Number.isFinite(memory.wall) || !Number.isSafeInteger(memory.epochSecond) ||
       memory.epochSecond!==Math.floor(memory.wall/1000) || !Number.isFinite(memory.now) || memory.now<0 ||
       (memory.until!==null && (!Number.isFinite(memory.until) || memory.until<=memory.now))))throw new Error('Invalid Live clock scheduling memory');
    // Replaying an earlier queued signal must not consume this wall-clock wake.
    if(context.historical && !fresh && memory.zone===zone){
      const nextWakeAt=memory.until===null?memory.now+1000-((memory.wall%1000+1000)%1000):memory.until;
      return {state,memory,nextWakeAt};
    }
    // Active-document time pauses while hidden. A wall/active-time discontinuity resets observation,
    // as does a backwards clock adjustment. Small scheduling jitter does not erase a normal tick.
    const restart=fresh || memory.zone!==zone || wall<memory.wall || now<memory.now ||
      Math.abs((wall-memory.wall)-(now-memory.now))>500;
    let secondTick=false,minuteTick=false,hourTick=false,halfDayTick=false,until=null;
    if(!restart){
      if(memory.until!==null){
        // An overdue high must fall before another rise; never turn missed ticks into a burst.
        if(now<memory.until){
          secondTick=state.second;minuteTick=state.minute;hourTick=state.hour;halfDayTick=state.halfDay;until=memory.until;
        }
      }else if(epochSecond===memory.epochSecond+1){
        secondTick=true;minuteTick=second===0;hourTick=minuteTick && minute===0;halfDayTick=hourTick && hour%12===0;
        until=now+100;
      }
    }
